using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Input;
using System.Windows.Data;

namespace DoonPanelPreview {
 public sealed partial class Workbench {
  // Read-only query grid, not an Excel engine. Filters run over all records.
  void Table(List<Dictionary<string,string>> rows,Action<Dictionary<string,string>> details){if(rows.Count==0){content.Children.Add(Label("暂无记录。"));return;}var fields=rows[0].Keys.Where(k=>!k.StartsWith("__")).ToList();var filters=new List<Func<Dictionary<string,string>,bool>>();var filterNames=new List<string>();var bar=new WrapPanel();var field=new ComboBox{ItemsSource=fields,SelectedIndex=0,Width=140,Margin=new Thickness(0,5,8,5)};var mode=new ComboBox{ItemsSource=new[]{"多选值","包含","不包含","等于","数值 ≥","数值 ≤","数值范围","空白"},SelectedIndex=0,Width=115,Margin=new Thickness(0,5,8,5)};var value=new TextBox{Width=160,Margin=new Thickness(0,5,8,5),ToolTip="范围格式：下限..上限"};var selected=new HashSet<string>();var summary=Label("");
   var grid=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,CanUserDeleteRows=false,Height=380,SelectionMode=DataGridSelectionMode.Single,HeadersVisibility=DataGridHeadersVisibility.Column,Background=Brushes.White,RowHeaderWidth=0};
   foreach(string f in fields){if(f==fields[0]){var link=new FrameworkElementFactory(typeof(Button));link.SetBinding(Button.ContentProperty,new Binding("["+f+"]"));link.SetValue(Button.BackgroundProperty,Brushes.Transparent);link.SetValue(Button.ForegroundProperty,green);link.SetValue(Button.BorderThicknessProperty,new Thickness(0));link.SetValue(Button.HorizontalContentAlignmentProperty,HorizontalAlignment.Left);link.SetValue(Button.CursorProperty,Cursors.Hand);link.AddHandler(Button.ClickEvent,new RoutedEventHandler((s,e)=>{var row=((FrameworkElement)s).DataContext as Dictionary<string,string>;if(row!=null)details(row);e.Handled=true;}));grid.Columns.Add(new DataGridTemplateColumn{Header=f,CellTemplate=new DataTemplate{VisualTree=link},Width=175});}else grid.Columns.Add(new DataGridTextColumn{Header=f,Binding=new Binding("["+f+"]"),Width=f=="状态"||f=="说明"?200:115});}
   Action refresh=()=>{var matched=rows.Where(r=>filters.All(test=>test(r))).ToList();grid.ItemsSource=matched;summary.Text="显示 "+matched.Count+" / "+rows.Count+" 条 · 条件："+(filterNames.Count==0?"全部":string.Join("；",filterNames));};
   field.SelectionChanged+=(s,e)=>selected.Clear();bar.Children.Add(field);bar.Children.Add(mode);bar.Children.Add(value);bar.Children.Add(Btn("选择字段值",()=>SelectValues(rows.Select(r=>r[(string)field.SelectedItem]).Distinct().OrderBy(x=>x).ToList(),selected)));
   bar.Children.Add(Btn("添加条件",()=>{string f=(string)field.SelectedItem,op=(string)mode.SelectedItem,v=value.Text;Func<Dictionary<string,string>,bool> test;string description=f+" "+op+" "+v;if(op=="多选值"){if(selected.Count==0)throw new InvalidDataException("请先选择字段值。");var chosen=new HashSet<string>(selected);test=r=>chosen.Contains(r[f]);description=f+" ∈ "+string.Join("、",chosen.Select(x=>x==""?"（空白）":x));}else if(op=="空白")test=r=>r[f]=="";else if(op.StartsWith("数值")){decimal? lo=null,hi=null;if(op=="数值范围"){var ends=v.Split(new[]{".."},StringSplitOptions.None);if(ends.Length==2){lo=PriceParser.Number(ends[0]);hi=PriceParser.Number(ends[1]);}if(!lo.HasValue||!hi.HasValue||lo>hi)throw new InvalidDataException("范围格式为 10..20，使用纯数字。");}else{var n=PriceParser.Number(v);if(!n.HasValue)throw new InvalidDataException("请输入纯数字。");if(op=="数值 ≥")lo=n;else hi=n;}test=r=>{var n=PriceParser.Number(r[f]);return n.HasValue&&(!lo.HasValue||n>=lo)&&(!hi.HasValue||n<=hi);};}else if(op=="等于")test=r=>string.Equals(r[f],v,StringComparison.OrdinalIgnoreCase);else test=r=>(r[f].IndexOf(v,StringComparison.OrdinalIgnoreCase)>=0)==(op=="包含");filters.Add(test);filterNames.Add(description);refresh();}));bar.Children.Add(Btn("清除筛选",()=>{filters.Clear();filterNames.Clear();refresh();}));content.Children.Add(bar);content.Children.Add(summary);
   Action open=()=>{var row=grid.SelectedItem as Dictionary<string,string>;if(row!=null)details(row);else MessageBox.Show(this,"请先选择一条记录。","查看详情");};grid.MouseDoubleClick+=(s,e)=>open();grid.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Enter){e.Handled=true;open();}};content.Children.Add(Btn("查看选中记录详情（也可双击记录）",open));content.Children.Add(grid);refresh();
  }
  void SelectValues(List<string> values,HashSet<string> selected){var d=new Window{Title="字段值 · 可搜索多选",Owner=this,Width=480,Height=540,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new DockPanel{Margin=new Thickness(20)};var search=new TextBox{Margin=new Thickness(0,0,0,12)};DockPanel.SetDock(search,Dock.Top);panel.Children.Add(search);var actions=new WrapPanel();DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);var list=new StackPanel();Action render=()=>{list.Children.Clear();foreach(string v in values.Where(x=>x.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0)){string item=v;var box=new CheckBox{Content=v==""?"（空白）":v,IsChecked=selected.Contains(v),Margin=new Thickness(3)};box.Checked+=(s,e)=>selected.Add(item);box.Unchecked+=(s,e)=>selected.Remove(item);list.Children.Add(box);}};actions.Children.Add(Btn("全选",()=>{foreach(var v in values)selected.Add(v);render();}));actions.Children.Add(Btn("反选",()=>{foreach(var v in values)if(!selected.Remove(v))selected.Add(v);render();}));actions.Children.Add(Btn("清除",()=>{selected.Clear();render();}));var done=Btn("完成",()=>d.Close());done.IsCancel=true;actions.Children.Add(done);search.TextChanged+=(s,e)=>render();panel.Children.Add(new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});d.Content=panel;render();d.ShowDialog();}
 }
}
